HDR = 'import Janus.Contracts.ErrorfRealCode64\nimport Janus.Contracts.RelocAmd64\nimport Janus.Contracts.ErrorfRealStageDefs\nimport Janus.Contracts.ErrorfMem\nimport Janus.Contracts.PoolSatAmd64\n\n/-!\n# Loop lemmas of the real-format `fmt.errorf` stub (amd64)\n\nGENERATED by `scripts/errorf/gen_loops64.py`: one decimal loop per number, one byte-copy loop per segment, each\nfor the stub `ErrorfRealCode64.code64` at its own loop head and exit, with the rest of the run as a continuation.\n-/\n\nnamespace Janus.Contracts.ErrorfRealLoops64\n\nopen Janus Janus.Amd64 Janus.Amd64.GoABI Janus.Amd64.Tactic Janus.Contracts Janus.Contracts.Toy Janus.Spec\n  Janus.Spec.Errorf Janus.Contracts.ErrorfMem\nopen Janus.Contracts.RelocAmd64 (codeProg64)\nopen Janus.Contracts.ErrorfRealCode64 (code64 E0)\n\nset_option maxRecDepth 100000\nset_option maxHeartbeats 0\n\n'
DIG = "theorem dig64_@N@ (s : State) :\n    ∀ (t : Nat) (R : Nat → W64) (m : Janus.Arm64.Memory) (F : Flags) (endp : Nat),\n      t < 2 ^ 64 → R 0 = BitVec.ofNat 64 t → R 13 = BitVec.ofNat 64 endp → R 1 = 10#64 →\n      (natBytes t).length ≤ endp → endp < 2 ^ 48 →\n      m.accessible (endp - (natBytes t).length) (natBytes t).length true = true →\n      ∀ Q : State → Prop,\n        (∀ (c : W64) (F' : Flags), ReachesRet (codeProg64 E0 code64) (retAddrOf s)\n          { s with regs := setRegF (setRegF (setRegF R 0 0#64) 13 (BitVec.ofNat 64 (endp - (natBytes t).length))) 2 c,\n                   flags := F', mem := putBytes m (endp - (natBytes t).length) (natBytes t), rip := @X@#64 } Q) →\n        ReachesRet (codeProg64 E0 code64) (retAddrOf s) { s with regs := R, flags := F, mem := m, rip := @H@#64 } Q := by\n  intro t\n  induction t using Nat.strongRecOn with\n  | _ t ih =>\n  intro R m F endp ht h0 h13 h1 hle hend hacc Q htail\n  have hpos := natBytes_length_pos t\n  have h1e : 1 ≤ endp := by omega\n  janus64_run [h0, h13, h1] until [@H@, @X@]\n  · -- exit\n    have ht10 : t < 10 := by omega\n    have hq : t / 10 = 0 := by omega\n    have := htail (BitVec.setWidth 64 (BitVec.setWidth 32 (BitVec.ofNat 64 (t % 10)) + 48#32))\n      { cf := some false, pf := some (parity (t / 10)), af := none, zf := some (decide (t / 10 = 0)),\n        sf := some (BitVec.ofNat 64 (t / 10)).msb, ovf := some false }\n    rw [natBytes_lt ht10] at this\n    simp only [List.length_singleton, putBytes_cons, putBytes_nil] at this ⊢\n    refine Eq.mpr (congrArg (fun st => ReachesRet (codeProg64 E0 code64) (retAddrOf s) st Q) ?_) this\n    congr 1\n    · have hsub : BitVec.ofNat 64 endp - 1#64 = BitVec.ofNat 64 (endp - 1) := by\n        apply BitVec.eq_of_toNat_eq\n        simp only [BitVec.toNat_sub, BitVec.toNat_ofNat]\n        omega\n      rw [hsub, hq]\n      funext i\n      simp only [setRegF]\n      by_cases e0 : i = 0 <;> by_cases e2 : i = 2 <;> by_cases e13 : i = 13 <;> simp_all\n    · congr 1\n      omega\n  · have h10 : 10 ≤ t := by omega\n    have hq : t / 10 < t := by omega\n    have hlen : (natBytes t).length = (natBytes (t / 10)).length + 1 := by\n      rw [natBytes_ge h10]; simp\n    have hpos' := natBytes_length_pos (t / 10)\n    have hdig : (t % 10 % 4294967296 + 48) % 256 = 48 + t % 10 := by omega\n    have hsub : BitVec.ofNat 64 endp - 1#64 = BitVec.ofNat 64 (endp - 1) := by\n      apply BitVec.eq_of_toNat_eq\n      simp only [BitVec.toNat_sub, BitVec.toNat_ofNat]\n      omega\n    rw [hdig, hsub]\n    refine ih (t / 10) hq _ _ _ (endp - 1) (by omega) (by simp [setRegF]) (by simp [setRegF]) (by simp [setRegF, h1])\n      (by omega) (by omega) ?_ Q ?_\n    · simp only [Janus.Arm64.Memory.accessible_writeLE]\n      exact Janus.Arm64.Memory.accessible_mono _ hacc (by omega) (by omega)\n    · intro c F'\n      have := htail c F'\n      refine Eq.mpr (congrArg (fun st => ReachesRet (codeProg64 E0 code64) (retAddrOf s) st Q) ?_) this\n      congr 1\n      · have e : endp - 1 - (natBytes (t / 10)).length = endp - (natBytes t).length := by omega\n        rw [e]\n        funext i\n        simp only [setRegF]\n        by_cases e0 : i = 0 <;> by_cases e2 : i = 2 <;> by_cases e13 : i = 13 <;> simp_all\n      · rw [putBytes_writeLE_comm _ _ _ _ _ (Or.inr (by omega))]\n        have e : endp - 1 - (natBytes (t / 10)).length = endp - (natBytes t).length := by omega\n        rw [e, natBytes_ge h10, putBytes_snoc]\n        simp only [List.length_append, List.length_singleton]\n        have e2 : endp - ((natBytes (t / 10)).length + 1) + (natBytes (t / 10)).length = endp - 1 := by omega\n        rw [e2]\n"
CPY = "theorem cpy64_@N@ (s : State) :\n    ∀ (cnt : Nat) (R : Nat → W64) (m : Janus.Arm64.Memory) (F : Flags) (src dst : Nat),\n      cnt < 2 ^ 48 → R 12 = BitVec.ofNat 64 cnt → R 7 = BitVec.ofNat 64 src → R 11 = BitVec.ofNat 64 dst →\n      src + cnt ≤ 2 ^ 48 → dst + cnt ≤ 2 ^ 48 →\n      (src + cnt ≤ dst ∨ dst + cnt ≤ src) →\n      (cnt = 0 ∨ m.accessible src cnt false = true) → (cnt = 0 ∨ m.accessible dst cnt true = true) →\n      ∀ Q : State → Prop,\n        (∀ (c : W64) (F' : Flags), ReachesRet (codeProg64 E0 code64) (retAddrOf s)\n          { s with regs := setRegF (setRegF (setRegF (setRegF R 7 (BitVec.ofNat 64 (src + cnt))) 11 (BitVec.ofNat 64 (dst + cnt))) 12 0#64) 0 c,\n                   flags := F', mem := putBytes m dst (strBytes m src cnt), rip := @X@#64 } Q) →\n        ReachesRet (codeProg64 E0 code64) (retAddrOf s) { s with regs := R, flags := F, mem := m, rip := @H@#64 } Q := by\n  intro cnt\n  induction cnt with\n  | zero =>\n    intro R m F src dst hc h12 h7 h11 hs hd hdis hsa hda Q htail\n    janus64_run [h12, h7, h11] until [@H@, @X@]\n    have := htail (R 0) { cf := some false, pf := some (parity 0), af := none, zf := some true, sf := some (0#64).msb, ovf := some false }\n    refine Eq.mpr (congrArg (fun st => ReachesRet (codeProg64 E0 code64) (retAddrOf s) st Q) ?_) this\n    congr 1\n    · funext i\n      simp only [setRegF, h7, h11, h12, Nat.add_zero]\n      by_cases e0 : i = 0 <;> by_cases e12 : i = 12 <;> by_cases e11 : i = 11 <;> by_cases e7 : i = 7 <;> simp_all\n  | succ cnt ih =>\n    intro R m F src dst hc h12 h7 h11 hs hd hdis hsa hda Q htail\n    have hsa' : m.accessible src (cnt + 1) false = true := by\n      rcases hsa with h | h; omega; exact h\n    have hda' : m.accessible dst (cnt + 1) true = true := by\n      rcases hda with h | h; omega; exact h\n    janus64_run [h12, h7, h11] until [@H@, @X@]\n    have hb : m.readLE src 1 % 18446744073709551616 = (m.bytes src).toNat := by\n      rw [Janus.Arm64.Memory.readLE_one]; exact Nat.mod_eq_of_lt (by have := (m.bytes src).isLt; omega)\n    have hb1 : m.readLE src 1 = (m.bytes src).toNat := by rw [Janus.Arm64.Memory.readLE_one]\n    rw [hb1]\n    have hdis' : src + 1 + cnt ≤ dst + 1 ∨ dst + 1 + cnt ≤ src + 1 := by omega\n    refine ih _ _ _ (src + 1) (dst + 1) (by omega) ?_ ?_ ?_ (by omega) (by omega) hdis' ?_ ?_ Q ?_\n    · simp [setRegF]; apply BitVec.eq_of_toNat_eq; simp [BitVec.toNat_sub, BitVec.toNat_ofNat]; omega\n    · simp [setRegF, h7]\n    · simp [setRegF, h11]\n    · by_cases hz : cnt = 0\n      · exact Or.inl hz\n      · exact Or.inr (by simp only [Janus.Arm64.Memory.accessible_writeLE]; exact Janus.Arm64.Memory.accessible_mono _ hsa' (by omega) (by omega))\n    · by_cases hz : cnt = 0\n      · exact Or.inl hz\n      · exact Or.inr (by simp only [Janus.Arm64.Memory.accessible_writeLE]; exact Janus.Arm64.Memory.accessible_mono _ hda' (by omega) (by omega))\n    · intro c F'\n      have := htail c F'\n      refine Eq.mpr (congrArg (fun st => ReachesRet (codeProg64 E0 code64) (retAddrOf s) st Q) ?_) this\n      congr 1\n      · funext i\n        simp only [setRegF, show dst + 1 + cnt = dst + (cnt + 1) by omega, show src + 1 + cnt = src + (cnt + 1) by omega]\n        by_cases e0 : i = 0 <;> by_cases e12 : i = 12 <;> by_cases e11 : i = 11 <;> by_cases e7 : i = 7 <;> simp_all\n      · have e : strBytes (m.writeLE dst 1 (m.bytes src).toNat) (src + 1) cnt = strBytes m (src + 1) cnt := by\n          have := strBytes_putBytes_out m dst [(m.bytes src).toNat] (src + 1) cnt (by simp; omega)\n          simpa [putBytes_cons] using this\n        rw [e, strBytes_succ, putBytes_cons]\n"
